using Bank.Payments.Adapters.In.Rest;
using Bank.Payments.Domain.Error;
using Bank.Payments.Domain.Port;

namespace Bank.Payments.Application;

public sealed class PayOrderService(
    PaymentOrderRepository orders,
    CompanyTariffRepository companyTariffs,
    ServiceCatalogRepository services,
    AccountRepository accounts,
    DebitGateway debit)
{
    public PayOrderResponse Execute(PayOrderRequest request)
    {
        var canal = request.Canal ?? "WEB";

        // RULE-001: permitted account types
        if (request.TipoCuenta is not ("CTE" or "AHO" or "VIR"))
        {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003: the order must exist
        var order = orders.FindByNumberAndCompany(request.Orden, request.Empresa);
        if (order is null)
        {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }

        // RULE-002: only pending orders
        if (order.Status != "P")
        {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004 / RULE-005: tariff resolution
        decimal? tariff;
        string? separada;
        var companyTariff = companyTariffs.FindByCompanyAndService(request.Empresa, request.Servicio);
        if (companyTariff is not null)
        {
            tariff = companyTariff.TariffValue;
            separada = companyTariff.ChargedSeparately;
        }
        else
        {
            var service = services.FindByCode(request.Servicio);
            tariff = service?.DefaultTariff;
            separada = "N";
        }

        var tariffValue = tariff ?? 0m;

        // RULE-006: commission by channel and NOMINA exemption
        decimal commission = canal == "WEB"
            ? Math.Round(tariffValue / 2m, 2, MidpointRounding.AwayFromZero)
            : tariffValue;
        if (request.Servicio == "NOMINA")
        {
            commission = 0m;
        }

        // RULE-007: amount to debit
        decimal? total = separada == "S" ? request.Valor : request.Valor + commission;

        // RULE-008: funds check (skipped when balance or total are unknown)
        var account = accounts.FindByNumberAndType(request.Cuenta, request.TipoCuenta);
        var balance = account?.Balance;
        if (balance.HasValue && total.HasValue)
        {
            var insufficient = request.TipoCuenta == "VIR"
                ? balance.Value < total.Value
                : balance.Value + 100.00m < total.Value;
            if (insufficient)
            {
                throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
            }
        }

        // RULE-009: debit the account
        int movement;
        try
        {
            movement = debit.DebitAccount(request.Cuenta, request.TipoCuenta, total, "PAGO ORDEN");
        }
        catch (Exception)
        {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        // RULE-010: separately charged commission
        if (separada == "S" && commission > 0m)
        {
            try
            {
                debit.DebitCommission(request.Cuenta, request.TipoCuenta, commission, "COMISION PAGO");
            }
            catch (Exception)
            {
                throw new BusinessError("COMMISSION_DEBIT_FAILED", "50006", "ERROR EN COMISION");
            }
        }

        // RULE-011: mark the order as paid
        var rows = orders.MarkPaid(request.Orden, request.Empresa, request.FechaProceso, commission);
        if (rows == 0)
        {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        return new PayOrderResponse(movement, "PAGO REALIZADO");
    }
}
